import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { GatsbyImage, IGatsbyImageData, getImage } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"

interface GalleryGroup {
  fieldValue: string
  nodes: Array<{
    childImageSharp: {
      gatsbyImageData: IGatsbyImageData
    }
  }>
}

interface ImageNode {
  childImageSharp: {
    gatsbyImageData: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    designGalleries: {
      group: GalleryGroup[]
    }
    artImages: {
      nodes: ImageNode[]
    }
  }
}

const CreationsPage: React.FC<PageProps> = ({ data }) => {
  // Get the first art image as the cover for the Art gallery card
  const artCoverImage = data.artImages.nodes[0]?.childImageSharp?.gatsbyImageData

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <h1>Creations</h1>
        <p>A collection of visual expressions — from digital designs to artistic explorations.</p>
        <div className="accent-line"></div>
      </div>
      <div className="galleries-container">
        <div className="galleries-grid">
          {/* Art Gallery Card */}
          <Link
            to="/creations/art"
            className="gallery-card"
          >
            {artCoverImage && (
              <GatsbyImage
                image={artCoverImage}
                alt="Art Gallery"
                className="gallery-cover"
              />
            )}
            <div className="gallery-info">
              <h2>Art</h2>
              <p>{data.artImages.nodes.length} {data.artImages.nodes.length === 1 ? 'piece' : 'pieces'}</p>
            </div>
          </Link>

          {/* Design Gallery Cards */}
          {data.designGalleries.group.map((gallery) => {
            const galleryName = gallery.fieldValue
            const galleryTitle = galleryName
              .split('-')
              .map(word => word.charAt(0).toUpperCase() + word.slice(1))
              .join(' ')

            // Use the last image as the cover
            const coverImage = gallery.nodes[gallery.nodes.length - 1]?.childImageSharp?.gatsbyImageData

            return (
              <Link
                key={galleryName}
                to={`/creations/${galleryName}`}
                className="gallery-card"
              >
                {coverImage && (
                  <GatsbyImage
                    image={coverImage}
                    alt={galleryTitle}
                    className="gallery-cover"
                  />
                )}
                <div className="gallery-info">
                  <h2>{galleryTitle}</h2>
                  <p>{gallery.nodes.length} {gallery.nodes.length === 1 ? 'design' : 'designs'}</p>
                </div>
              </Link>
            )
          })}
        </div>
      </div>
      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query CreationsQuery {
    designGalleries: allFile(
      filter: {
        sourceInstanceName: { eq: "design" }
        relativeDirectory: { ne: "" }
      }
      sort: { relativeDirectory: ASC }
    ) {
      group(field: { relativeDirectory: SELECT }) {
        fieldValue
        nodes {
          childImageSharp {
            gatsbyImageData(
              width: 800
              height: 800
              placeholder: BLURRED
              transformOptions: { fit: COVER, cropFocus: CENTER }
            )
          }
        }
      }
    }
    artImages: allFile(
      filter: { sourceInstanceName: { eq: "art" } }
      sort: { name: ASC }
      limit: 1
    ) {
      nodes {
        childImageSharp {
          gatsbyImageData(
            width: 300
            height: 300
            placeholder: BLURRED
            transformOptions: { fit: COVER, cropFocus: CENTER }
          )
        }
      }
    }
  }
`

export default CreationsPage
